import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";
import { dsFontSizes, dsTypeRecipes } from "./generated/ds-classes";

// Both lists are generated from theme.css (scripts/build-foundations.mjs).
// - `text-ds-<size>` must count as a font size, not a colour, or it would
//   clash with `text-ds-text`.
// - `ds-type-*` recipes are one group, so a later recipe (e.g. from
//   `className`) replaces the earlier one (e.g. from `variant`), and a recipe
//   replaces earlier loose typography utilities it already sets.
const twMerge = extendTailwindMerge<"ds-type">({
  extend: {
    classGroups: {
      "font-size": [{ text: dsFontSizes }],
      "ds-type": dsTypeRecipes,
    },
    conflictingClassGroups: {
      "ds-type": [
        "font-size",
        "font-weight",
        "leading",
        "tracking",
        "font-family",
      ],
    },
  },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// GENERATED by scripts/build-foundations.mjs from styles/theme.css. Do not edit.
/** Values for the `text-<size>` utilities (font-size namespace). */
export const dsFontSizes: string[] = ["ds-display", "ds-h1", "ds-h2", "ds-h3", "ds-body", "ds-lead", "ds-caption", "ds-label", "ds-control-sm", "ds-control-md"];
/** `.ds-type-<role>` recipe classes (each sets family, size, weight, leading, tracking). */
export const dsTypeRecipes: string[] = ["ds-type-display", "ds-type-h1", "ds-type-h2", "ds-type-h3", "ds-type-body", "ds-type-lead", "ds-type-caption", "ds-type-label"];
